@@ -7,20 +7,125 @@

 /** Parse a version string. See README.md for the accepted syntax. */
 export function parseVersion(text: string): Version {
-  throw new Error("not implemented");
+  // Trim whitespace and remove leading 'v' if present
+  const trimmed = text.trim();
+  const versionStr = trimmed.startsWith('v') ? trimmed.slice(1) : trimmed;
+
+  // Split into main version and pre-release/build metadata parts
+  const [versionAndPrerelease, buildMetadata] = versionStr.split('+');
+  const [versionPart, ...preReleaseParts] = versionAndPrerelease.split('-');
+  
+  // Parse main version numbers
+  const versionNumbers = versionPart.split('.');
+  if (versionNumbers.length !== 3) {
+    throw new Error("invalid version: incorrect number of version parts");
+  }
+  
+  const [majorStr, minorStr, patchStr] = versionNumbers;
+  const major = parseInt(majorStr, 10);
+  const minor = parseInt(minorStr, 10);
+  const patch = parseInt(patchStr, 10);
+  
+  // Validate numeric parts
+  if (isNaN(major) || isNaN(minor) || isNaN(patch)) {
+    throw new Error("invalid version: non-numeric version parts");
+  }
+  
+  // Parse pre-release identifiers if present
+  let prerelease: string[] = [];
+  if (preReleaseParts.length > 0) {
+    const prereleaseStr = preReleaseParts.join('-');
+    if (prereleaseStr === '') {
+      throw new Error("invalid version: empty pre-release part");
+    }
+    prerelease = prereleaseStr.split('.');
+  }
+  
